head.script:
            scwin.trigger1_onclick = function() {
                tabControl1.addTab("sub1", {
                    "label": "sub1",
                    "title": "sub1",
                    "openAction": "exist",
                    "closable": "true"
                },
                {
                    "src": "tabControl_spaAuto_windowMaxNum_WESD-1675_(WSQ-5738)_sub.xml",
                    "frameMode": "iframe",
                    "alwaysDraw": "true"
                });
            };
            scwin.trigger2_onclick = function() {
                tabControl1.addTab("sub2", {
                    "label": "sub2",
                    "title": "sub2",
                    "openAction": "exist",
                    "closable": "true"
                },
                {
                    "src": "tabControl_spaAuto_windowMaxNum_WESD-1675_(WSQ-5738)_sub.xml",
                    "frameMode": "iframe",
                    "alwaysDraw": "true"
                });
            };
            scwin.trigger3_onclick = function() {
                tabControl1.addTab("sub3", {
                    "label": "sub3",
                    "title": "sub3",
                    "openAction": "exist",
                    "closable": "true"
                },
                {
                    "src": "/tabControl/sub3.xml",
                    "frameMode": "iframe",
                    "alwaysDraw": "true"
                });
            };

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_1_iframe_0').querySelector('iframe') != null;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_1_iframe_0') === null;
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_1_iframe_1').querySelector('iframe') != null;
	}	
	scwin.unitTest = function(){
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "1500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
